const A='assets/';
let kinescopeApiPromise;
function kinescopePreview(id,title,options={}){const poster=options.poster||'video-posters/kinescope-'+id+'.jpg';const autoplay=options.autoplay||options.background;return `<div class="kinescope-frame" data-kinescope-id="${id}" data-muted="${options.muted?'1':'0'}" data-loop="${options.loop?'1':'0'}" data-autoplay="${autoplay?'1':'0'}" data-quality="${options.quality||'auto'}" aria-label="${title}"><div class="kinescope-player"></div><img class="kinescope-poster" src="${A+poster}" alt="" loading="lazy"><button class="kinescope-play" type="button" aria-label="Воспроизвести: ${title}"><span aria-hidden="true">▶</span></button></div>`}
function loadKinescopeApi(){if(window.Kinescope?.IframePlayer)return Promise.resolve();if(!kinescopeApiPromise)kinescopeApiPromise=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://player.kinescope.io/latest/iframe.player.js';s.onload=resolve;s.onerror=()=>reject(new Error('Не удалось загрузить плеер Kinescope'));document.head.appendChild(s)});return kinescopeApiPromise}
async function startKinescopePlayer(frame){if(frame.dataset.ready)return;frame.dataset.ready='1';const target=frame.querySelector('.kinescope-player');target.id='kinescope-player-'+Math.random().toString(36).slice(2);const autoplay=frame.dataset.autoplay==='1';try{await loadKinescopeApi();const player=await window.Kinescope.IframePlayer.create(target.id,{url:'https://kinescope.io/embed/'+frame.dataset.kinescopeId+'?quality='+encodeURIComponent(frame.dataset.quality||'auto'),size:{width:'100%',height:'100%'},behavior:{autoPlay:true,muted:autoplay||frame.dataset.muted==='1',loop:autoplay||frame.dataset.loop==='1',playsInline:true},ui:{controls:!autoplay,mainPlayButton:!autoplay,videoFit:'cover'}});frame._kinescopePlayer=player;player.on('playing',()=>frame.classList.add('is-playing'));player.on('ended',()=>frame.classList.remove('is-playing'));player.on('error',()=>{frame.dataset.ready='';frame.classList.remove('is-playing');frame.classList.add('is-error')})}catch(err){frame.dataset.ready='';frame.classList.add('is-error');console.error(err)}}
function initKinescopeVideos(root=document){root.querySelectorAll('.kinescope-frame:not([data-initialized])').forEach(frame=>{frame.dataset.initialized='1';frame.querySelector('.kinescope-play')?.addEventListener('click',()=>{const player=frame._kinescopePlayer;if(player?.play){const playback=player.play();playback?.catch?.(err=>console.error(err));return}if(!frame.dataset.ready)startKinescopePlayer(frame)});if(frame.dataset.autoplay==='1'){if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting)){observer.disconnect();startKinescopePlayer(frame)}},{rootMargin:'180px'});observer.observe(frame)}else startKinescopePlayer(frame)}})}
