function localVideoPreview(src,title,poster){const [width,height]=localVideoDimensions(src);return `<div class="case-media case-embed local-video-frame" aria-label="${title}"><video playsinline muted loop data-lazy-video="1" preload="none" width="${width}" height="${height}" poster="${A+poster}" aria-label="${title}"><source data-src="${A+src}" type="video/mp4"></video><button class="kinescope-play local-video-play" type="button" aria-label="Воспроизвести: ${title}"><span aria-hidden="true">▶</span></button></div>`}
let clipObserver;
function initLocalVideos(root=document){
 if(!clipObserver && 'IntersectionObserver' in window)clipObserver=new IntersectionObserver(entries=>{for(const e of entries){const v=e.target;if(!v.isConnected){clipObserver.unobserve(v);continue}if(e.isIntersecting&&!document.hidden&&!matchMedia('(prefers-reduced-motion: reduce)').matches){v._startClip?.()}else v.pause()}},{threshold:0.12});
 root.querySelectorAll('video[data-lazy-video="1"]:not([data-lazy-init])').forEach(v=>{v.dataset.lazyInit='1';v.muted=true;v.loop=true;const source=v.querySelector('source[data-src]');if(!source)return;v._startClip=()=>{if(source.dataset.src){source.src=source.dataset.src;delete source.dataset.src;v.load()}v.play().catch(()=>{v.controls=true})};if(clipObserver)clipObserver.observe(v);else v.controls=true;v.addEventListener('click',()=>{if(v.paused)v._startClip();else v.pause()});if(matchMedia('(prefers-reduced-motion: reduce)').matches){v.controls=true;v.addEventListener('play',()=>{if(source.dataset.src)v._startClip()})}});
 root.querySelectorAll('.local-video-frame:not([data-local-init])').forEach(frame=>{frame.dataset.localInit='1';const v=frame.querySelector('video'),source=v?.querySelector('source'),button=frame.querySelector('.local-video-play');if(!v||!source||!button)return;button.addEventListener('click',()=>{if(v.dataset.lazyVideo==='1'){v._startClip?.();return}if(source.dataset.src){source.src=source.dataset.src;delete source.dataset.src;v.controls=true;v.load()}v.play().catch(()=>{})});v.addEventListener('playing',()=>frame.classList.add('is-playing'));v.addEventListener('ended',()=>frame.classList.remove('is-playing'))});
}
document.addEventListener('visibilitychange',()=>{if(document.hidden)document.querySelectorAll('video[data-lazy-video="1"]').forEach(v=>v.pause());else document.querySelectorAll('video[data-lazy-video="1"]').forEach(v=>{if(clipObserver){clipObserver.unobserve(v);clipObserver.observe(v)}})});

function playerSrc(url){return url}
function kinescopeId(url){return String(url||'').split('/').filter(Boolean).pop().split(/[?#]/)[0]}
