function renderIndex(category='all'){
 const allProjects=projects.filter(p=>p.listed!==false);
 const projectOrder=['karlsson','samarkand','computer','tmh','amazing','fingers','cpp-explainer','catalog','research','trevoga','twin'];
 allProjects.sort((a,b)=>{const ai=projectOrder.indexOf(a.id),bi=projectOrder.indexOf(b.id);return (ai<0?projectOrder.length:ai)-(bi<0?projectOrder.length:bi)});
 const visible=allProjects.filter(p=>category==='all'||(p.filters||[p.filter]).includes(category));
 const cards=visible.map((p,index)=>'<a class="index-card index-card-'+p.id+'" href="#project/'+p.id+'"><div class="index-thumb" style="background:'+(p.cardBg||'#e8ecf2')+'"><img src="'+A+p.cover+'" alt="'+p.title+'" loading="lazy" style="object-position:'+(p.position||'center')+';object-fit:'+(p.fit||'cover')+'"></div><div class="index-card-bottom"><div><h3>'+p.title+'</h3><div class="index-tags">'+tagMarkup(p.indexLabel||p.type)+'</div></div><b>↗︎</b></div></a>').join('');
 byId('project-index').innerHTML=cards;
 normalizeArrows(byId('project-index'));
}
renderIndex();
