 if(item.type==='heading')return `<section class="case-media-heading"><h2>${item.url?`<a class="case-section-link" href="${item.url}" target="_blank" rel="noopener noreferrer">${item.text} <span class="case-section-arrow" aria-hidden="true">↗</span></a>`:item.text}</h2>${item.description?`<p>${item.description}</p>`:''}</section>`;
