 if(item.type==='carousel')return `<section class="case-carousel ${item.variant||''}" aria-label="${item.label||title}"><div class="case-carousel-track" tabindex="0">${(item.slides||[]).map(slide=>`<div class="case-carousel-slide">${slide.type==='image'?`<img src="${A+slide.src}" alt="${slide.alt||item.label||title}" loading="lazy">`:`${kinescopePreview(slide.id,slide.title||item.label||title,slide)}`}</div>`).join('')}</div><div class="case-carousel-controls"><button type="button" data-carousel-step="-1" aria-label="Предыдущий слайд"><svg viewBox="0 0 16 16" aria-hidden="true"><path d="M13 8H3m4-4-4 4 4 4"></path></svg></button><button type="button" data-carousel-step="1" aria-label="Следующий слайд"><svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3 8h10M9 4l4 4-4 4"></path></svg></button></div></section>`;
 return '';
