function normalizeArrows(root=document.body){
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())if(/[↗↘↑↓←→]/.test(walker.currentNode.nodeValue))nodes.push(walker.currentNode);
 const paths={'↗':'M4 12 12 4M5 4h7v7','↘':'M4 4 12 12M5 12h7V5','↑':'M8 13V4m-4 4 4-4 4 4','↓':'M8 3v9m-4-4 4 4 4-4','←':'M13 8H4m4-4-4 4 4 4','→':'M3 8h9m-4-4 4 4-4 4'};
 for(const node of nodes){const frag=document.createDocumentFragment();const parts=node.nodeValue.replace(/\uFE0E/g,'').split(/([↗↘↑↓←→])/);for(const part of parts){if(paths[part]){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 16 16');svg.setAttribute('class','arrow-icon');svg.setAttribute('aria-hidden','true');const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',paths[part]);svg.appendChild(path);frag.appendChild(svg)}else if(part)frag.appendChild(document.createTextNode(part))}node.replaceWith(frag)}
}
function initCaseCarousels(root){
 root.querySelectorAll('.case-carousel').forEach(carousel=>{
  const track=carousel.querySelector('.case-carousel-track');
  const slides=[...track.children];
  carousel.querySelectorAll('[data-carousel-step]').forEach(button=>button.addEventListener('click',()=>{
   const current=Math.round(track.scrollLeft/Math.max(1,track.clientWidth));
   const next=Math.max(0,Math.min(slides.length-1,current+Number(button.dataset.carouselStep)));
   track.scrollTo({left:slides[next].offsetLeft,behavior:'smooth'});
  }));
 });
}
function syncSkillSeparators(root=document){root.querySelectorAll('.skill-items').forEach(group=>{const items=[...group.querySelectorAll('.skill-item:not(.skill-full-row)')];items.forEach((item,index)=>{const next=items[index+1];item.classList.toggle('skill-row-last',!next||Math.abs(next.offsetTop-item.offsetTop)>1)});group.querySelectorAll('.skill-full-row').forEach(item=>item.classList.add('skill-row-last'))})}
let skillSeparatorResizeObserver;
function observeSkillSeparators(root=document){if(skillSeparatorResizeObserver)skillSeparatorResizeObserver.disconnect();const groups=root.querySelectorAll('.skill-items');if(!groups.length)return;skillSeparatorResizeObserver=new ResizeObserver(()=>syncSkillSeparators(root));groups.forEach(group=>skillSeparatorResizeObserver.observe(group));syncSkillSeparators(root);if(document.fonts?.ready)document.fonts.ready.then(()=>syncSkillSeparators(root))}
window.addEventListener('resize',()=>syncSkillSeparators());
function route(){document.querySelectorAll('#case video').forEach(v=>{v.pause();clipObserver?.unobserve(v)});const h=location.hash;const p=h.startsWith('#project/')?projects.find(x=>x.id===h.split('/')[1]):null;const cv=h==='#cv';document.body.classList.toggle('tmh-active',!!p&&p.id==='tmh');document.body.classList.toggle('samarkand-active',!!p&&p.id==='samarkand');document.body.classList.toggle('karlsson-active',!!p&&p.id==='karlsson');document.body.classList.toggle('computer-active',!!p&&p.id==='computer');document.body.classList.toggle('amazing-active',!!p&&p.id==='amazing');document.body.classList.toggle('fingers-active',!!p&&p.id==='fingers');document.body.classList.toggle('catalog-active',!!p&&p.id==='catalog');document.body.classList.toggle('research-active',!!p&&p.id==='research');document.body.classList.toggle('trevoga-active',!!p&&p.id==='trevoga');document.body.classList.toggle('twin-active',!!p&&p.id==='twin');document.body.classList.toggle('cpp-explainer-active',!!p&&p.id==='cpp-explainer');byId('app').hidden=!!p||cv;byId('case').hidden=!(p||cv);if(p||cv){byId('case').innerHTML=p?casePage(p):cvPage();window.scrollTo(0,0);normalizeArrows(byId('case'));observeSkillSeparators(byId('case'));initCaseCarousels(byId('case'));initLocalVideos(byId('case'));initKinescopeVideos(byId('case'))}else if(h&&document.querySelector(h)){setTimeout(()=>document.querySelector(h)?.scrollIntoView(),20)}document.querySelector('nav').classList.remove('open');document.querySelector('.mobile-menu').setAttribute('aria-expanded','false')}
function keepShortWordsWithNext(root){if(!root)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes)node.nodeValue=node.nodeValue.replace(/(\s)(в|во|к|ко|с|со|у|о|об|от|до|из|за|на|по|под|при|для|без|над|перед|между|и|а|но|или|либо|не)\s+(?=[А-Яа-яЁё0-9«])/giu,'$1$2\u00a0')}
keepShortWordsWithNext(document.querySelector('.intro-text'));window.addEventListener('hashchange',route);route();normalizeArrows();initLocalVideos(document);initKinescopeVideos(document);
