const dialog=byId('reel-dialog');dialog.addEventListener('close',()=>dialog.querySelectorAll('video').forEach(v=>v.pause()));const openReel=()=>{dialog.showModal();initLocalVideos(dialog);setTimeout(()=>dialog.querySelector('.local-video-play')?.click(),0)};byId('hero-reel').onclick=openReel;byId('reel-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
